64	+// configureFlowDeps contains side effects used by the interactive configure
65	+// flow. Tests can replace individual operations without a keyring, browser,
66	+// GitHub CLI, or live control plane.
67	+type configureFlowDeps struct {
68	+	resolveAuth  func(context.Context) (statusTarget, error)
69	+	fetchProfile profileFetcher
70	+	runLogin     func(context.Context, io.Writer, io.Writer) error
