83	+		fetchProfile: defaultFetchProfile,
84	+		runLogin: func(ctx context.Context, outW, errW io.Writer) error {
85	+			cmd := newLoginCmd()
86	+			cmd.SetContext(ctx)
87	+			cmd.SetOut(outW)
88	+			cmd.SetErr(errW)
89	+			return cmd.RunE(cmd, nil)
90	+		},
91	+		accessClient: func(ctx context.Context) (configureAccessReporter, error) {
92	+			return NewAuthenticatedAPIClient(ctx, insecure)
