101	+// runConfigureOnboarding is a seam for command tests. Bare interactive
102	+// `entire configure` is the new end-to-end entry point; flag-based configure
103	+// remains the non-interactive settings editor.
104	+var runConfigureOnboarding = func(cmd *cobra.Command, opts EnableOptions) error {
105	+	return runConfigureOnboardingFlow(cmd, opts, newConfigureFlowDeps(false))
106	+}
