108	+func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
109	+	cmd.SilenceUsage = true
110	+	ctx := cmd.Context()
111	+	outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
112	+
113	+	repoRoot, err := paths.WorktreeRoot(ctx)
114	+	if err != nil {
115	+		fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
116	+		return NewSilentError(errors.New("not a git repository"))
117	+	}
118	+	owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
119	+	if err != nil {
120	+		return err
121	+	}
122	+
123	+	profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
124	+	if err != nil {
125	+		return err
126	+	}
127	+
128	+	reporter, err := deps.accessClient(ctx)
129	+	if err != nil {
130	+		return fmt.Errorf("connect to Entire: %w", err)
131	+	}
132	+	access, err := reporter.ReportEnable(ctx, cleanRemote)
133	+	if err != nil {
134	+		return fmt.Errorf("check repository access: %w", err)
135	+	}
136	+	if !access.Connected {
137	+		if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, opts.Yes, deps); err != nil {
138	+			return err
139	+		}
140	+	}
141	+
142	+	client, err := deps.coreClient()
143	+	if err != nil {
144	+		return fmt.Errorf("connect to Entire control plane: %w", err)
145	+	}
146	+	placements, err := resolvePullablePlacements(ctx, client, owner, repo)
147	+	if err != nil {
148	+		return renderCoreError(err)
149	+	}
150	+	if len(placements) == 0 {
151	+		placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction, opts.Yes)
152	+		if err != nil {
153	+			return err
154	+		}
155	+	}
156	+	if len(placements) == 0 {
157	+		return errors.New("no usable mirror was selected")
158	+	}
159	+
160	+	manageRegionsHint := ""
161	+	if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
162	+		manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
163	+			configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
164	+	}
165	+	initialChanges, err := configureGitChanges(ctx, repoRoot)
166	+	if err != nil {
167	+		return err
168	+	}
169	+	branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
170	+	if branchErr != nil {
171	+		// Best-effort: local-only saves do not need a branch.
172	+		branch = ""
173	+	}
174	+	protected := false
175	+	protectionKnown := branch == ""
176	+	if branch != "" {
177	+		if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
178	+			protected = detected
179	+			protectionKnown = true
180	+		}
181	+	}
182	+	// Non-interactive onboarding has no confirmation step. If GitHub protection
183	+	// cannot be checked (common when gh is unavailable in CI), fail closed and
184	+	// use the review branch rather than pushing directly to the checked-out
185	+	// branch. Interactive users can still explicitly choose a direct push when
186	+	// protection is known not to block it.
187	+	protected = configureEffectiveProtection(protected, protectionKnown, opts.Yes)
188	+	branchPushSafe := false
189	+	if branch != "" && len(initialChanges) == 0 {
190	+		branchPushSafe = configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)
191	+	}
192	+	chosen, selectedAgents, saveChoice, agentsChanged, err := promptConfigureUpstreamAndAgents(
193	+		ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
194	+		branch, protected, branchPushSafe, opts.Yes,
195	+	)
196	+	if err != nil {
197	+		return err
198	+	}
199	+	if saveChoice == configureSaveCancel {
200	+		fmt.Fprintln(outW, "Configuration cancelled.")
201	+		return nil
202	+	}
203	+	if saveChoice == "" {
204	+		fmt.Fprintln(outW, "No configuration changes.")
205	+		return nil
206	+	}
207	+
208	+	// Snapshot immediately before applying our changes. The form may have been
209	+	// open for an arbitrary amount of time, so the pre-form status is not a safe
210	+	// commit baseline: editor autosaves or another process may have changed files
211	+	// while the user was choosing options. Anything already dirty now is excluded
212	+	// from generated and disables automatic commit/push below.
213	+	beforeApply, err := configureGitChanges(ctx, repoRoot)
214	+	if err != nil {
215	+		return err
216	+	}
217	+	if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
218	+		(len(beforeApply) != 0 || !configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)) {
219	+		saveChoice = configureSaveLocal
220	+	}
221	+
222	+	forgeRemote, err := configureUseMirror(ctx, outW, errW, repoRoot, owner, repo, chosen)
223	+	if err != nil {
224	+		return err
225	+	}
226	+
227	+	if agentsChanged {
228	+		opts = configureOnboardingEnableOptions(opts)
229	+		if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
230	+			return err
231	+		}
232	+		// A local enabled:false override must not win over the newly written project
233	+		// configuration. setEnabledFlag updates the project and synchronizes an
234	+		// existing local override without replacing its other local-only fields.
235	+		if err := setEnabledFlag(ctx, true, true); err != nil {
236	+			return err
237	+		}
238	+	}
239	+
240	+	after, err := configureGitChanges(ctx, repoRoot)
241	+	if err != nil {
242	+		return err
243	+	}
244	+	generated := newConfigureChanges(beforeApply, after)
245	+	if agentsChanged {
246	+		fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
247	+	}
248	+
249	+	if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
250	+		if err := configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, deps.now); err != nil {
251	+			return err
252	+		}
253	+	} else if agentsChanged && len(generated) > 0 {
254	+		fmt.Fprintln(outW, "  Configuration was saved locally. Review and commit it normally when ready.")
255	+	}
256	+	fmt.Fprintln(outW, "✓ Configuration complete")
257	+	fmt.Fprintln(outW)
258	+	fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
259	+	fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
260	+	return nil
261	+}
