263	+func configureOnboardingEnableOptions(opts EnableOptions) EnableOptions {
264	+	opts.Yes = true
265	+	opts.UseProjectSettings = true
266	+	opts.UseLocalSettings = false
267	+	opts.SuppressDoneMessage = true
268	+	opts.SuppressAdditionalSetup = true
269	+	// Logged-in onboarding does not ask a separate telemetry question. The
270	+	// documented default is applied without prompting; existing settings and
271	+	// ENTIRE_TELEMETRY_OPTOUT remain authoritative.
272	+	return opts
273	+}
