279	+func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
280	+	raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
281	+	if err != nil {
282	+		return "", "", "", fmt.Errorf("read origin remote: %w", err)
283	+	}
284	+	info, err := gitremote.ParseURL(raw)
285	+	if err != nil {
286	+		return "", "", "", fmt.Errorf("parse origin remote: %w", err)
287	+	}
288	+	if info.Forge != mirrorUseForge {
289	+		return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
290	+	}
291	+	clean, err := cleanRemoteURLForReport(raw)
292	+	if err != nil {
293	+		return "", "", "", err
294	+	}
295	+	return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
296	+}
