298	+func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
299	+	target, err := deps.resolveAuth(ctx)
300	+	if err != nil {
301	+		return nil, err
302	+	}
303	+	if target.token != "" {
304	+		if err := api.RequireSecureURL(target.coreURL); err != nil {
305	+			return nil, fmt.Errorf("context login server URL check: %w", err)
306	+		}
307	+		if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
308	+			return profile, nil
309	+		} else if !isKeychainTokenRejected(profileErr) {
310	+			return nil, fmt.Errorf("validate login: %w", profileErr)
311	+		}
312	+	}
313	+
314	+	if err := deps.runLogin(ctx, outW, errW); err != nil {
315	+		return nil, fmt.Errorf("login: %w", err)
316	+	}
317	+	target, err = deps.resolveAuth(ctx)
318	+	if err != nil {
319	+		return nil, err
320	+	}
321	+	if target.token == "" {
322	+		return nil, errors.New("login completed without an active session")
323	+	}
324	+	if err := api.RequireSecureURL(target.coreURL); err != nil {
325	+		return nil, fmt.Errorf("context login server URL check: %w", err)
326	+	}
327	+	profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
328	+	if err != nil {
329	+		return nil, fmt.Errorf("validate login: %w", err)
330	+	}
331	+	fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
332	+	return profile, nil
333	+}
334	+
335	+func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, nonInteractive bool, deps configureFlowDeps) error {
336	+	fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
337	+	installURL := strings.TrimSpace(initial.InstallURL)
338	+	if installURL == "" {
339	+		installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
340	+	}
341	+
342	+	admin, adminErr := deps.githubAdmin(ctx, owner, repo)
343	+	if adminErr == nil && !admin {
344	+		fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
345	+		fmt.Fprintln(errW, "  Send them this link to continue:")
346	+		fmt.Fprintf(errW, "\n  %s\n", installURL)
347	+		return NewSilentError(errors.New("GitHub app installation required"))
348	+	}
349	+	if adminErr != nil {
350	+		switch {
351	+		case errors.Is(adminErr, errConfigureGHUnavailable):
352	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
353	+			fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
354	+		case errors.Is(adminErr, errConfigureGHUnauthenticated):
355	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
356	+			fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
357	+		default:
358	+			fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
359	+		}
360	+		fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
361	+		fmt.Fprintln(errW)
362	+	}
363	+
364	+	fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
365	+	fmt.Fprintf(outW, "  %s\n\n", installURL)
366	+	if nonInteractive {
367	+		return NewSilentError(errors.New("GitHub app installation required; install it with the URL above, then rerun 'entire configure --yes'"))
368	+	}
369	+	if err := deps.openURL(ctx, installURL); err != nil {
370	+		fmt.Fprintln(outW, "  Open the link above in your browser.")
371	+	}
372	+	stop := startSpinner(errW, "Waiting for installation")
373	+	stopped := false
374	+	defer func() {
375	+		if !stopped {
376	+			stop(false)
377	+		}
378	+	}()
379	+
380	+	waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
381	+	defer cancel()
382	+	ticker := time.NewTicker(configureAccessPollInterval)
383	+	defer ticker.Stop()
384	+	for {
385	+		select {
386	+		case <-waitCtx.Done():
387	+			return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
388	+		case <-ticker.C:
389	+			access, err := reporter.ReportEnable(waitCtx, cleanRemote)
390	+			if err == nil && access.Connected {
391	+				stop(true)
392	+				stopped = true
393	+				fmt.Fprintln(outW, "✓ Access granted")
394	+				return nil
395	+			}
396	+		}
397	+	}
398	+}
