400	+func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
401	+	runner := execRunner{}
402	+	if !ghAvailable(ctx, runner) {
403	+		return false, errConfigureGHUnavailable
404	+	}
405	+	if !ghAuthenticated(ctx, runner) {
406	+		return false, errConfigureGHUnauthenticated
407	+	}
408	+	out, err := runner.Run(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin")
409	+	if err != nil {
410	+		return false, fmt.Errorf("check GitHub admin permission: %w", err)
411	+	}
412	+	admin, err := strconv.ParseBool(strings.TrimSpace(out))
413	+	if err != nil {
414	+		return false, fmt.Errorf("parse GitHub admin permission: %w", err)
415	+	}
416	+	return admin, nil
417	+}
