419	+func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string, nonInteractive bool) ([]coreapi.ResolvedPlacement, error) {
420	+	regions, err := availableRegions(ctx, client)
421	+	if err != nil {
422	+		return nil, fmt.Errorf("list regions: %w", err)
423	+	}
424	+	if len(regions) == 0 {
425	+		return nil, errors.New("no regions available to mirror into")
426	+	}
427	+	selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction, nonInteractive)
428	+	if err != nil {
429	+		return nil, err
430	+	}
431	+	results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
432	+	reportErr := reportMirrorResults(outW, errW, results)
433	+	placements := configureSuccessfulMirrorPlacements(selected, results)
434	+	if len(placements) > 0 {
435	+		if reportErr != nil {
436	+			fmt.Fprintf(errW, "Continuing with %d mirror(s) that succeeded.\n", len(placements))
437	+		}
438	+		return placements, nil
439	+	}
440	+	if reportErr != nil {
441	+		return nil, reportErr
442	+	}
443	+	return nil, errors.New("no usable mirrors were created")
444	+}
445	+
446	+func configureSuccessfulMirrorPlacements(selected []regionChoice, results []mirrorResult) []coreapi.ResolvedPlacement {
447	+	placements := make([]coreapi.ResolvedPlacement, 0, len(results))
448	+	for i, result := range results {
449	+		if i >= len(selected) || result.err != nil || result.cloneURL == "" {
450	+			continue
451	+		}
452	+		region := selected[i]
453	+		placements = append(placements, coreapi.ResolvedPlacement{
454	+			ClusterHost:  region.host,
455	+			Cell:         coreapi.NewOptString(region.slug),
456	+			Jurisdiction: coreapi.NewOptString(region.jurisdiction),
457	+		})
458	+	}
459	+	return placements
460	+}
