462	+func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string, nonInteractive bool) ([]regionChoice, error) {
463	+	opts, defaults := clusterChoices(regions, jurisdiction)
464	+	byHost := make(map[string]regionChoice, len(regions))
465	+	for _, region := range regions {
466	+		byHost[region.host] = region
467	+	}
468	+	selected := append([]string(nil), defaults...)
469	+	if nonInteractive {
470	+		if len(selected) == 0 && len(opts) > 0 {
471	+			selected = append(selected, opts[0].Value)
472	+		}
473	+		chosen := make([]regionChoice, 0, len(selected))
474	+		for _, host := range selected {
475	+			if region, ok := byHost[host]; ok {
476	+				chosen = append(chosen, region)
477	+			}
478	+		}
479	+		return chosen, nil
480	+	}
481	+	form := NewAccessibleForm(huh.NewGroup(
482	+		huh.NewMultiSelect[string]().
483	+			Title("Which regions should this repository live in?").
484	+			Description("Space to select, enter to confirm — your data stays in the selected regions.").
485	+			Options(opts...).
486	+			Height(multiSelectHeight(len(opts))).
487	+			Validate(func(values []string) error {
488	+				if len(values) == 0 {
489	+					return errors.New("select at least one region")
490	+				}
491	+				return nil
492	+			}).
493	+			Value(&selected),
494	+	))
495	+	if err := form.RunWithContext(ctx); err != nil {
496	+		if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
497	+			return nil, cancelErr
498	+		}
499	+		return nil, NewSilentError(errors.New("configure cancelled"))
500	+	}
501	+	chosen := make([]regionChoice, 0, len(selected))
502	+	for _, host := range selected {
503	+		if region, ok := byHost[host]; ok {
504	+			chosen = append(chosen, region)
505	+		}
506	+	}
507	+	return chosen, nil
508	+}
