+type configureSaveField struct {
+	*huh.Select[string]
+
+	focused bool
+}
+
+func (field *configureSaveField) Focus() tea.Cmd {
+	field.focused = true
+	return tea.Batch(field.Select.Focus(), configureRefreshFocus())
+}
+
+func (field *configureSaveField) Blur() tea.Cmd {
